import { parseChartSpec, type TaggedBlock } from "@agentdock-ai/ui-core";
import { ChartFrame } from "./chart-frame";
import { ChartBar } from "./chart-bar";
import { ChartLine } from "./chart-line";
import { ChartPie } from "./chart-pie";
import { ChartFallback, ChartSkeleton } from "./chart-fallback";
export function ChartBlock({ block }: { block: TaggedBlock }) {
  if (block.state === "streaming")
    return <ChartSkeleton title={block.attributes.title} />;
  if (block.state === "unterminated")
    return (
      <ChartFallback
        reason="The closing chart tag is missing."
        raw={block.raw}
      />
    );
  const parsed = parseChartSpec(block.attributes, block.body);
  if (!parsed.ok)
    return <ChartFallback reason={parsed.reason} raw={block.raw} />;
  const { spec } = parsed;
  return (
    <ChartFrame spec={spec}>
      {spec.type === "pie" ? (
        <ChartPie spec={spec} />
      ) : spec.type === "bar" ? (
        <ChartBar spec={spec} />
      ) : (
        <ChartLine spec={spec} />
      )}
    </ChartFrame>
  );
}

import type { ReactNode } from "react";
import {
  chartLayout,
  CHART_PLOT,
  formatValue,
  type CartesianChartSpec,
} from "@agentdock-ai/ui-core";
export function ChartCartesian({
  spec,
  children,
}: {
  spec: CartesianChartSpec;
  children: ReactNode;
}) {
  const { ticks, x, y } = chartLayout(spec);
  return (
    <svg
      viewBox="0 0 600 220"
      className="h-[220px] w-full overflow-visible"
      aria-label={`${spec.type} chart`}
    >
      {ticks.map((tick) => (
        <g key={tick}>
          <line
            x1={CHART_PLOT.left}
            x2={CHART_PLOT.right}
            y1={y(tick)}
            y2={y(tick)}
            className="stroke-border"
          />
          <text
            x={CHART_PLOT.left - 8}
            y={y(tick) + 4}
            textAnchor="end"
            className="fill-muted-foreground text-[16px]"
          >
            {formatValue(tick, spec.unit)}
          </text>
        </g>
      ))}
      {spec.x.map(
        (label, i) =>
          i % Math.max(1, Math.ceil(spec.x.length / 10)) === 0 && (
            <text
              key={i}
              x={x(i)}
              y={204}
              textAnchor="middle"
              className="fill-muted-foreground text-[16px]"
            >
              {String(label).slice(0, 16)}
            </text>
          ),
      )}
      {children}
    </svg>
  );
}

