"use client";
import { useEffect, useRef, useState } from "react";
import { LoaderCircle } from "lucide-react";
import { ChatIcon } from "./icon";
import { Button } from "./ui/button";

export function formatElapsed(ms: number) {
  const seconds = Math.floor(ms / 1000);
  if (seconds < 60) return `${seconds}s`;
  return `${Math.floor(seconds / 60)}m ${String(seconds % 60).padStart(2, "0")}s`;
}

/** Live status line: what is happening, the running step and elapsed time. */
export function ThinkingIndicator({
  label = "thinking",
  startedAt,
  step,
  longAfterMs = 30_000,
  onStop,
}: {
  label?: "thinking" | "working";
  /** ISO timestamp or epoch ms; elapsed time shows once mounted. */
  startedAt?: string | number;
  /** The step in progress, such as `{ label: "Searching the web", tool: "web_search" }`. */
  step?: { label: string; tool?: string };
  /** After this long the line offers Stop and says the step is slow. */
  longAfterMs?: number;
  onStop?: () => void;
}) {
  const start =
    typeof startedAt === "string" ? Date.parse(startedAt) : startedAt;
  const [now, setNow] = useState<number | null>(null);
  useEffect(() => {
    if (start === undefined || !Number.isFinite(start)) return;
    setNow(Date.now());
    const timer = setInterval(() => setNow(Date.now()), 1000);
    return () => clearInterval(timer);
  }, [start]);
  const elapsed =
    start !== undefined && Number.isFinite(start) && now !== null
      ? Math.max(0, now - start)
      : null;
  const long = elapsed !== null && elapsed >= longAfterMs;
  const text = long
    ? "Still working"
    : (step?.label ?? (label === "working" ? "Working" : "Thinking"));
  return (
    <div className="flex min-w-0 flex-col gap-0.5 px-1">
      <div className="flex min-h-7 min-w-0 items-center gap-2 text-[13px] leading-5 text-muted-foreground">
        {step || long ? (
          <ChatIcon
            icon={LoaderCircle}
            size={13}
            className="text-foreground motion-safe:animate-spin"
          />
        ) : (
          <Dots />
        )}
        <span aria-hidden="true" className="text-foreground">
          {text}
        </span>
        {step?.tool && (
          <span aria-hidden="true" className="truncate font-mono text-xs">
            {step.tool}
          </span>
        )}
        {elapsed !== null && (
          <span aria-hidden="true" className="font-mono text-xs tabular-nums">
            {formatElapsed(elapsed)}
          </span>
        )}
        {long && onStop && (
          <Button
            variant="outline"
            className="ml-auto min-h-7 px-2.5 text-[12.5px]"
            onClick={onStop}
          >
            Stop
          </Button>
        )}
      </div>
      {long && (
        <p className="text-xs leading-[18px] text-muted-foreground">
          This step is taking longer than usual.
        </p>
      )}
    </div>
  );
}

/** Three staggered dots via the Web Animations API; still under reduced motion. */
function Dots() {
  const ref = useRef<HTMLSpanElement>(null);
  useEffect(() => {
    const element = ref.current;
    if (
      !element ||
      (typeof matchMedia === "function" &&
        matchMedia("(prefers-reduced-motion: reduce)").matches)
    )
      return;
    const animations = [...element.children].flatMap((dot, index) =>
      typeof dot.animate === "function"
        ? [
            dot.animate([{ opacity: 0.2 }, { opacity: 1 }, { opacity: 0.2 }], {
              duration: 1200,
              delay: index * 200,
              iterations: Infinity,
            }),
          ]
        : [],
    );
    return () => animations.forEach((animation) => animation.cancel());
  }, []);
  return (
    <span
      ref={ref}
      aria-hidden="true"
      className="flex w-4 shrink-0 items-center justify-between text-foreground"
    >
      <span className="size-[3px] rounded-full bg-current" />
      <span className="size-[3px] rounded-full bg-current" />
      <span className="size-[3px] rounded-full bg-current" />
    </span>
  );
}

"use client";
import { useEffect, useRef, useState, type ReactNode } from "react";
import { Check, LoaderCircle, Search, SquarePen, X } from "lucide-react";
import { ChatIcon } from "./icon";
const doubleClickDelayMs = 250;
export interface ChatThread {
  id: string;
  title: string;
  /** Show activity while the app's agent is running this thread. */
  isRunning?: boolean;
}
/** Controlled navigation only. The app owns threads, persistence and authorization. */
export function ThreadSidebar({
  threads,
  selectedId,
  onSelect,
  onNew,
  onRename,
  footer,
}: {
  threads: readonly ChatThread[];
  selectedId: string;
  onSelect: (id: string) => void;
  onNew: () => void;
  onRename?: (id: string, title: string) => void;
  footer?: ReactNode;
}) {
  const [search, setSearch] = useState("");
  const [renamingId, setRenamingId] = useState<string | null>(null);
  const [draft, setDraft] = useState("");
  const pendingSelection = useRef<ReturnType<typeof setTimeout> | null>(null);
  useEffect(
    () => () => {
      if (pendingSelection.current) clearTimeout(pendingSelection.current);
    },
    [],
  );
  function selectThread(id: string) {
    if (pendingSelection.current) clearTimeout(pendingSelection.current);
    pendingSelection.current = setTimeout(() => {
      pendingSelection.current = null;
      onSelect(id);
    }, doubleClickDelayMs);
  }
  function renameThread(thread: ChatThread) {
    if (pendingSelection.current) clearTimeout(pendingSelection.current);
    pendingSelection.current = null;
    setDraft(thread.title);
    setRenamingId(thread.id);
  }
  const visible = threads.filter((thread) =>
    thread.title.toLowerCase().includes(search.toLowerCase()),
  );
  return (
    <nav
      aria-label="Threads"
      className="flex h-full min-h-0 flex-col text-[13px]"
    >
      <div className="space-y-2 px-3 pb-2 pt-1">
        <button
          type="button"
          data-thread-navigation
          onClick={onNew}
          className="flex min-h-8 w-full items-center gap-2 rounded-lg px-2.5 text-left font-medium outline-none transition-colors duration-150 hover:bg-background/80 focus-visible:ring-2 focus-visible:ring-ring/60 motion-reduce:transition-none [@media(pointer:coarse)]:min-h-10"
        >
          <ChatIcon icon={SquarePen} size={15} aria-hidden="true" />
          New thread
        </button>
        <label className="flex min-h-8 items-center gap-2 rounded-lg border border-border/70 bg-background px-2.5 text-muted-foreground transition-colors duration-150 focus-within:border-ring/60 motion-reduce:transition-none">
          <ChatIcon icon={Search} size={14} aria-hidden="true" />
          <input
            aria-label="Search threads"
            value={search}
            onChange={(event) => setSearch(event.target.value)}
            placeholder="Search threads"
            className="min-w-0 flex-1 bg-transparent py-1 text-[13px] text-foreground outline-none placeholder:text-muted-foreground [@media(pointer:coarse)]:text-base"
          />
        </label>
      </div>
      <div className="min-h-0 flex-1 overflow-auto px-3 pb-3">
        <p className="px-2.5 pb-1.5 pt-3 text-[11px] font-medium uppercase tracking-[0.06em] text-muted-foreground">
          Conversations
        </p>
        <ul className="space-y-0.5">
          {visible.map((thread) => (
            <li key={thread.id}>
              {renamingId === thread.id ? (
                <form
                  className="flex min-h-8 items-center gap-1"
                  onSubmit={(event) => {
                    event.preventDefault();
                    const title = draft.trim();
                    if (title && onRename) onRename(thread.id, title);
                    setRenamingId(null);
                  }}
                >
                  <input
                    autoFocus
                    aria-label="Conversation title"
                    value={draft}
                    onChange={(event) => setDraft(event.target.value)}
                    maxLength={200}
                    className="min-w-0 flex-1 rounded-lg border border-ring/60 bg-background px-2.5 py-1 outline-none ring-4 ring-ring/10"
                  />
                  <button
                    type="submit"
                    aria-label="Save title"
                    className="flex size-7 items-center justify-center rounded-lg text-muted-foreground outline-none hover:bg-background hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring/60"
                  >
                    <ChatIcon icon={Check} size={14} />
                  </button>
                  <button
                    type="button"
                    aria-label="Cancel rename"
                    onClick={() => setRenamingId(null)}
                    className="flex size-7 items-center justify-center rounded-lg text-muted-foreground outline-none hover:bg-background hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring/60"
                  >
                    <ChatIcon icon={X} size={14} />
                  </button>
                </form>
              ) : (
                <div className="group flex min-h-8 items-center gap-1">
                  <button
                    type="button"
                    aria-current={selectedId === thread.id ? "page" : undefined}
                    data-thread-navigation
                    data-thread-editable={onRename ? "" : undefined}
                    onClick={() =>
                      onRename ? selectThread(thread.id) : onSelect(thread.id)
                    }
                    onDoubleClick={() => onRename && renameThread(thread)}
                    title={thread.title}
                    aria-label={`${thread.title}${thread.isRunning ? ", agent is working" : ""}`}
                    className={`flex min-h-8 min-w-0 flex-1 items-center gap-2 rounded-lg px-2.5 py-1 text-left outline-none transition-colors duration-150 focus-visible:ring-2 focus-visible:ring-ring/60 motion-reduce:transition-none [@media(pointer:coarse)]:min-h-10 ${selectedId === thread.id ? "bg-background font-medium text-foreground shadow-[0_1px_2px_0_rgb(0_0_0/0.06)] ring-1 ring-border/70" : "text-muted-foreground hover:bg-background/60 hover:text-foreground"}`}
                  >
                    <span className="min-w-0 flex-1 truncate">
                      {thread.title}
                    </span>
                    {thread.isRunning && (
                      <span
                        title="Agent is working"
                        className="flex shrink-0 items-center text-muted-foreground"
                      >
                        <ChatIcon
                          icon={LoaderCircle}
                          size={13}
                          aria-hidden="true"
                          className="motion-safe:animate-spin"
                        />
                      </span>
                    )}
                  </button>
                </div>
              )}
            </li>
          ))}
        </ul>
        {!visible.length && (
          <p className="px-2.5 py-2 text-xs text-muted-foreground">
            No conversations found
          </p>
        )}
      </div>
      {footer && (
        <div className="shrink-0 border-t border-border/70 px-5 py-3 text-xs text-muted-foreground">
          {footer}
        </div>
      )}
    </nav>
  );
}

"use client";
import { ArtifactOpenButton } from "./artifact-open-button";
import { useState } from "react";
import { Check, ChevronRight, LoaderCircle, Square, X } from "lucide-react";
import { ChatIcon } from "./icon";
import type { RenderToolCallItem } from "@agentdock-ai/ui-core";
import {
  Collapsible,
  CollapsibleContent,
  CollapsibleTrigger,
} from "./ui/collapsible";
import { PulseDot, toneText } from "./alert";
import { formatElapsed } from "./thinking-indicator";
import { cn, errorDetail, formatJson } from "./utils";

export function ToolCall({ item }: { item: RenderToolCallItem }) {
  const [open, setOpen] = useState(false);
  const [copied, setCopied] = useState(false);
  const { tool, active } = item;
  const failed = tool.status === "failed";
  const running = active && tool.status === "running";
  const status = failed
    ? "Failed"
    : tool.status === "approval"
      ? "Needs approval"
      : running
        ? "Running"
        : tool.status === "complete"
          ? "Complete"
          : "Stopped";
  const progress = running
    ? tool.progress
        .flatMap((part) => (part.type === "text" ? [part.text] : []))
        .at(-1)
    : undefined;
  const started = tool.startedAt ? Date.parse(tool.startedAt) : NaN;
  const completed = tool.completedAt ? Date.parse(tool.completedAt) : NaN;
  const duration =
    Number.isFinite(started) && Number.isFinite(completed)
      ? formatDuration(completed - started)
      : undefined;
  const message = failed
    ? errorDetail(
        tool.error ??
          (typeof tool.output === "string"
            ? tool.output
            : "The tool returned an error."),
      )
    : undefined;

  return (
    <Collapsible open={open} onOpenChange={setOpen} className="min-w-0">
      <div className="flex min-w-0 items-center gap-2">
        <CollapsibleTrigger
          aria-label={`${tool.name} ${status}`}
          className="group/tool flex min-h-7 w-full max-w-full min-w-0 items-center gap-2 rounded-md text-left text-[13px] leading-5 text-muted-foreground outline-none transition-colors duration-150 hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring/60 motion-reduce:transition-none [@media(pointer:coarse)]:min-h-10"
        >
          <span className="flex w-3.5 shrink-0 justify-center">
            {running ? (
              <ChatIcon
                icon={LoaderCircle}
                size={13}
                className="text-foreground motion-safe:animate-spin"
              />
            ) : tool.status === "approval" ? (
              <PulseDot />
            ) : (
              <ChatIcon
                icon={failed ? X : tool.status === "complete" ? Check : Square}
                size={13}
                className={
                  failed
                    ? toneText.error
                    : tool.status === "complete"
                      ? toneText.success
                      : undefined
                }
              />
            )}
          </span>
          <span className="min-w-0 truncate font-mono text-[12.5px] text-foreground/90">
            {tool.name}
          </span>
          {status !== "Complete" && (
            <span
              className={cn(
                "shrink-0 text-[12px]",
                failed && cn("font-medium", toneText.error),
                tool.status === "approval" &&
                  cn("font-medium", toneText.warning),
              )}
            >
              {status}
            </span>
          )}
          {duration && (
            <span className="shrink-0 font-mono text-[12px] tabular-nums">
              {duration}
            </span>
          )}
          <ChatIcon
            icon={ChevronRight}
            size={13}
            aria-hidden="true"
            className={`ml-auto shrink-0 transition-[transform,opacity] duration-200 motion-reduce:transition-none ${open ? "rotate-90 opacity-100" : "opacity-0 group-hover/tool:opacity-100 group-focus-visible/tool:opacity-100 [@media(hover:none)]:opacity-50"}`}
          />
        </CollapsibleTrigger>
        <ArtifactOpenButton toolCallId={tool.toolCallId} />
      </div>
      {progress && (
        <p
          role="status"
          className="mb-1 ml-[1.375rem] line-clamp-2 text-[12px] leading-5 text-muted-foreground [overflow-wrap:anywhere]"
        >
          {progress}
        </p>
      )}
      {failed && !open && (
        <p className="mb-1 ml-[1.375rem] line-clamp-1 text-[12px] leading-5 text-muted-foreground [overflow-wrap:anywhere]">
          {message}
        </p>
      )}
      <CollapsibleContent>
        <div className="mb-2 ml-[1.375rem] mt-1 space-y-2.5">
          <Payload title="Input" value={tool.input} />
          {tool.progress.length > 0 && (
            <Payload
              title="Progress"
              value={tool.progress
                .map((part) => ("text" in part ? part.text : formatJson(part)))
                .join("\n")}
            />
          )}
          {tool.output !== undefined && !failed && (
            <Payload title="Output" value={tool.output} />
          )}
          {failed && (
            <div className="flex min-w-0 flex-wrap items-center gap-x-3 gap-y-1 text-[13px] leading-5">
              <p
                role="alert"
                className="min-w-0 flex-1 [overflow-wrap:anywhere]"
              >
                <span className={cn("font-medium", toneText.error)}>
                  {message}
                </span>{" "}
                {tool.errorCode && (
                  <span className="font-mono text-[12px] text-muted-foreground">
                    {tool.errorCode}
                  </span>
                )}
              </p>
              <button
                type="button"
                onClick={() => {
                  void navigator.clipboard
                    ?.writeText(
                      [tool.errorCode, message].filter(Boolean).join(": "),
                    )
                    .then(() => setCopied(true))
                    .catch(() => setCopied(false));
                }}
                className="shrink-0 rounded text-xs font-medium text-muted-foreground outline-none hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring/60"
              >
                {copied ? "Copied" : "Copy error"}
              </button>
            </div>
          )}
        </div>
      </CollapsibleContent>
    </Collapsible>
  );
}

function formatDuration(ms: number) {
  if (!Number.isFinite(ms) || ms < 0) return undefined;
  return ms < 10_000 ? `${(ms / 1000).toFixed(1)}s` : formatElapsed(ms);
}

function Payload({ title, value }: { title: string; value: unknown }) {
  return (
    <div className="min-w-0">
      <p className="mb-1 text-[12px] leading-4 text-muted-foreground">
        {title}
      </p>
      <pre
        tabIndex={0}
        aria-label={title}
        className="max-h-60 max-w-full overflow-auto whitespace-pre-wrap rounded-lg border border-border bg-muted/30 px-3 py-2 font-mono text-[12px] leading-5 text-foreground/80 outline-none focus-visible:ring-2 focus-visible:ring-ring/60 [overflow-wrap:anywhere]"
      >
        {formatJson(value)}
      </pre>
    </div>
  );
}

