import { useEffect, useRef } from "react";
/** Native modal dialogs supply focus trapping and inert the chat on small screens. */
export function useArtifactDialog(fullscreen: boolean) {
  const ref = useRef<HTMLDialogElement>(null);
  useEffect(() => {
    const dialog = ref.current;
    if (!dialog) return;
    const previous = document.activeElement;
    const query = window.matchMedia?.("(max-width: 767px)");
    function show() {
      if (!dialog) return;
      if (dialog.open) dialog.close?.();
      if (query?.matches || fullscreen) {
        dialog.showModal?.();
        dialog.setAttribute("aria-modal", "true");
      } else {
        dialog.show?.();
        dialog.removeAttribute("aria-modal");
      }
      // Non-browser renderers may not implement the native dialog methods.
      dialog.setAttribute("open", "");
    }
    show();
    query?.addEventListener("change", show);
    return () => {
      query?.removeEventListener("change", show);
      dialog.close?.();
      if (previous instanceof HTMLElement && previous.isConnected)
        previous.focus();
    };
  }, [fullscreen]);
  return ref;
}

import {
  useEffect,
  useState,
  type KeyboardEvent,
  type PointerEvent,
} from "react";
const key = "agentdock.artifact-width";
const clamp = (width: number) => Math.min(75, Math.max(25, width));
function initialWidth() {
  try {
    const stored = Number(localStorage.getItem(key));
    return Number.isFinite(stored) && stored > 0 ? clamp(stored) : 45;
  } catch {
    return 45;
  }
}
export function useArtifactSplit() {
  const [width, setWidth] = useState(initialWidth);
  const [dragging, setDragging] = useState(false);
  useEffect(() => {
    try {
      localStorage.setItem(key, String(width));
    } catch {
      /* Storage is optional in restricted contexts. */
    }
  }, [width]);
  function onKeyDown(event: KeyboardEvent<HTMLElement>) {
    const next =
      event.key === "ArrowLeft"
        ? width + 2
        : event.key === "ArrowRight"
          ? width - 2
          : event.key === "Home"
            ? 25
            : event.key === "End"
              ? 75
              : undefined;
    if (next !== undefined) {
      event.preventDefault();
      setWidth(clamp(next));
    }
  }
  function onPointerMove(event: PointerEvent<HTMLElement>) {
    if (!dragging) return;
    const rect = event.currentTarget.parentElement?.getBoundingClientRect();
    if (rect?.width)
      setWidth(clamp(((rect.right - event.clientX) / rect.width) * 100));
  }
  return {
    width,
    divider: {
      onKeyDown,
      onPointerMove,
      onPointerDown(event: PointerEvent<HTMLElement>) {
        event.preventDefault();
        event.currentTarget.setPointerCapture?.(event.pointerId);
        setDragging(true);
      },
      onPointerUp() {
        setDragging(false);
      },
      onLostPointerCapture() {
        setDragging(false);
      },
    },
  };
}

import { useEffect, useState } from "react";
import type { Artifact } from "@agentdock-ai/ui-core";
export function useArtifactTabs(artifacts: readonly Artifact[]) {
  const [tabs, setTabs] = useState<string[]>([]);
  const [activeId, setActive] = useState<string>();
  const [visible, setVisible] = useState(false);
  const [chosen, setChosen] = useState<Record<string, number | undefined>>({});
  const [seen, setSeen] = useState<Record<string, number>>({});
  const active = artifacts.find((a) => a.id === activeId);
  const latest = active?.versions.length ?? 0;
  useEffect(() => {
    if (activeId && visible)
      setSeen((current) => ({ ...current, [activeId]: latest }));
  }, [activeId, latest, visible]);
  return {
    tabs: tabs.filter((id) => artifacts.some((a) => a.id === id)),
    activeId,
    visible,
    chosen,
    seen,
    open(id: string) {
      setTabs((current) => (current.includes(id) ? current : [...current, id]));
      setActive(id);
      setVisible(true);
    },
    close(id: string) {
      const remaining = tabs.filter((tab) => tab !== id);
      setTabs(remaining);
      if (activeId === id) setActive(remaining.at(-1));
      if (!remaining.length) setVisible(false);
    },
    selectVersion(id: string, version?: number) {
      setChosen((current) => ({ ...current, [id]: version }));
    },
    dismiss() {
      setVisible(false);
    },
  };
}

import { useEffect, useState } from "react";
/** Blob URLs belong only to this mounted viewer and are always revoked. */
export function useArtifactUrl(content: string | undefined, mimeType: string) {
  const [url, setUrl] = useState<string>();
  useEffect(() => {
    if (content === undefined) {
      setUrl(undefined);
      return;
    }
    const next = URL.createObjectURL(new Blob([content], { type: mimeType }));
    setUrl(next);
    return () => URL.revokeObjectURL(next);
  }, [content, mimeType]);
  return url;
}

"use client";
import { useEffect, useRef, useState } from "react";
import type {
  ChatAttachment,
  ChatAttachmentAdapter,
} from "@agentdock-ai/react";
import { errorDetail } from "./utils";

export interface AttachmentDraft {
  id: string;
  file: File;
  previewUrl?: string;
  status: "uploading" | "ready" | "error";
  attachment?: ChatAttachment;
  error?: string;
}

function accepts(file: File, accept?: string) {
  if (!accept) return true;
  return accept.split(",").some((entry) => {
    const value = entry.trim().toLowerCase();
    return value.startsWith(".")
      ? file.name.toLowerCase().endsWith(value)
      : value.endsWith("/*")
        ? file.type.toLowerCase().startsWith(value.slice(0, -1))
        : file.type.toLowerCase() === value;
  });
}

/** Draft lifetime only. The app adapter owns uploads, validation and storage. */
export function useChatAttachments(adapter?: ChatAttachmentAdapter) {
  const [items, setItems] = useState<AttachmentDraft[]>([]);
  const [error, setError] = useState("");
  const current = useRef<AttachmentDraft[]>([]);
  const uploads = useRef(new Map<string, AbortController>());
  const mounted = useRef(true);
  const publish = (next: AttachmentDraft[]) => {
    current.current = next;
    setItems(next);
  };
  const release = (item: AttachmentDraft) => {
    uploads.current.get(item.id)?.abort();
    uploads.current.delete(item.id);
    if (item.previewUrl) URL.revokeObjectURL(item.previewUrl);
  };
  useEffect(() => {
    mounted.current = true;
    return () => {
      mounted.current = false;
      current.current.forEach(release);
    };
  }, []);

  async function upload(item: AttachmentDraft) {
    if (!adapter) return;
    const controller = new AbortController();
    uploads.current.set(item.id, controller);
    try {
      const attachment = await adapter.upload({
        file: item.file,
        signal: controller.signal,
      });
      if (
        controller.signal.aborted ||
        !current.current.some((draft) => draft.id === item.id)
      )
        return;
      publish(
        current.current.map((draft) =>
          draft.id === item.id
            ? { ...draft, status: "ready", attachment }
            : draft,
        ),
      );
    } catch (cause) {
      if (controller.signal.aborted) return;
      const message =
        cause instanceof Error
          ? errorDetail(cause.message)
          : "The file could not be uploaded.";
      publish(
        current.current.map((draft) =>
          draft.id === item.id
            ? { ...draft, status: "error", error: message }
            : draft,
        ),
      );
    } finally {
      if (uploads.current.get(item.id) === controller)
        uploads.current.delete(item.id);
    }
  }
  return {
    items,
    error,
    blocked: items.some((item) => item.status !== "ready"),
    add(files: readonly File[]) {
      if (!adapter) return;
      setError("");
      for (const file of files) {
        if (
          current.current.some(
            (item) =>
              item.file.name === file.name &&
              item.file.size === file.size &&
              item.file.lastModified === file.lastModified,
          )
        )
          continue;
        if (
          adapter.maxFiles !== undefined &&
          current.current.length >= adapter.maxFiles
        ) {
          setError(`You can attach up to ${adapter.maxFiles} files.`);
          break;
        }
        if (!accepts(file, adapter.accept)) {
          setError(`This file type is not supported: ${file.name}`);
          continue;
        }
        if (
          adapter.maxFileSize !== undefined &&
          file.size > adapter.maxFileSize
        ) {
          setError(
            `File is too large: ${file.name}. Maximum ${Math.round(adapter.maxFileSize / 1_000_000)} MB.`,
          );
          continue;
        }
        const item: AttachmentDraft = {
          id: crypto.randomUUID(),
          file,
          status: "uploading",
          ...(file.type.startsWith("image/") && file.type !== "image/svg+xml"
            ? { previewUrl: URL.createObjectURL(file) }
            : {}),
        };
        publish([...current.current, item]);
        void upload(item);
      }
    },
    remove(id: string) {
      const item = current.current.find((draft) => draft.id === id);
      if (item) release(item);
      publish(current.current.filter((draft) => draft.id !== id));
      setError("");
    },
    retry(id: string) {
      const item = current.current.find((draft) => draft.id === id);
      if (!item || item.status !== "error") return;
      publish(
        current.current.map((draft) =>
          draft.id === id ? { ...draft, status: "uploading" } : draft,
        ),
      );
      void upload(item);
    },
    take() {
      const sent = current.current;
      publish([]);
      setError("");
      sent.forEach(release);
      return sent;
    },
    restore(sent: readonly AttachmentDraft[]) {
      if (!mounted.current) return;
      const restored = sent.map((item) => ({
        ...item,
        previewUrl: item.previewUrl
          ? URL.createObjectURL(item.file)
          : undefined,
      }));
      publish([...restored, ...current.current]);
    },
  };
}

import { useEffect, useState } from "react";
export function useLinkEmbed(
  url: string | undefined,
  canEmbed?: (url: string) => Promise<boolean>,
) {
  const [state, setState] = useState<{
    url?: string;
    value: "checking" | "allowed" | "blocked";
  }>({ value: "checking" });
  useEffect(() => {
    let live = true;
    if (!url || !canEmbed) return;
    setState({ url, value: "checking" });
    Promise.resolve()
      .then(() => canEmbed(url))
      .then(
        (allowed) => {
          if (live) setState({ url, value: allowed ? "allowed" : "blocked" });
        },
        () => {
          if (live) setState({ url, value: "allowed" });
        },
      );
    return () => {
      live = false;
    };
  }, [url, canEmbed]);
  return !canEmbed ? "allowed" : state.url === url ? state.value : "checking";
}

export function cn(...values: (string | false | null | undefined)[]) {
  return values.filter(Boolean).join(" ");
}
export function safeUrl(value?: string): string | undefined {
  if (!value) return undefined;
  try {
    const origin = globalThis.location?.origin ?? "http://localhost";
    if (value.startsWith("//") || value.startsWith("\\\\")) return undefined;
    const explicitScheme = /^[a-z][a-z0-9+.-]*:/i.test(value);
    const url = new URL(value, origin);
    if (explicitScheme)
      return ["https:", "http:", "mailto:"].includes(url.protocol)
        ? value
        : undefined;
    if (url.origin !== origin) return undefined;
    return `${url.pathname}${url.search}${url.hash}`;
  } catch {
    return undefined;
  }
}
export function errorDetail(value: string) {
  return safeDiagnosticText(value).split("\n")[0]?.slice(0, 240);
}
export function safeDiagnosticText(value: string) {
  return /(?:bearer\s|api[_ -]?key|authorization|\bat\s+\S+\s*\(|stack trace|sk-[\w-]{8})/i.test(
    value,
  )
    ? "This operation could not be completed."
    : value;
}
export function formatJson(value: unknown) {
  return typeof value === "string" ? value : JSON.stringify(value, null, 2);
}

